python3 << 'EOF'
import subprocess

# Read symbols
symbols = []
with open('/tmp/mono_syms.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            name = parts[2]
            symbols.append((addr, name))

symbols.sort()

def resolve(pc):
    # Binary search for largest symbol address <= pc
    lo, hi = 0, len(symbols) - 1
    result = None
    while lo <= hi:
        mid = (lo + hi) // 2
        if symbols[mid][0] <= pc:
            result = symbols[mid]
            lo = mid + 1
        else:
            hi = mid - 1
    if result:
        offset = pc - result[0]
        return f"{result[1]}+0x{offset:x}"
    return "???"

